const menuToggle = document.querySelector('.menu-toggle');
const mainNav = document.querySelector('#mainNav');
menuToggle?.addEventListener('click', () => {
  const open = mainNav.classList.toggle('open');
  menuToggle.setAttribute('aria-expanded', String(open));
  menuToggle.textContent = open ? '×' : '☰';
});
mainNav?.querySelectorAll('a').forEach(link => link.addEventListener('click', () => {
  mainNav.classList.remove('open'); menuToggle?.setAttribute('aria-expanded', 'false');
  if (menuToggle) menuToggle.textContent = '☰';
}));
const themeToggle = document.querySelector('#themeToggle');
const savedTheme = localStorage.getItem('portfolio-theme');
if (savedTheme === 'light') document.body.classList.add('light');
function updateThemeIcon(){ if(themeToggle) themeToggle.textContent = document.body.classList.contains('light') ? '☾' : '☼'; }
updateThemeIcon();
themeToggle?.addEventListener('click', () => {
  document.body.classList.toggle('light');
  localStorage.setItem('portfolio-theme', document.body.classList.contains('light') ? 'light' : 'dark');
  updateThemeIcon();
});
const searchInput = document.querySelector('#projectSearch');
const filterButtons = [...document.querySelectorAll('.filter-chip')];
const projectCards = [...document.querySelectorAll('.project-card')];
const noResults = document.querySelector('#noResults');
let activeFilter = 'all';
function filterProjects(){
  const query = (searchInput?.value || '').trim().toLowerCase(); let visible = 0;
  projectCards.forEach(card => {
    const category = card.dataset.category || '';
    const haystack = `${card.dataset.search || ''} ${card.innerText}`.toLowerCase();
    const matchesFilter = activeFilter === 'all' || category === activeFilter;
    const matchesQuery = !query || haystack.includes(query);
    card.hidden = !(matchesFilter && matchesQuery); if(!card.hidden) visible++;
  });
  if(noResults) noResults.hidden = visible !== 0;
}
searchInput?.addEventListener('input', filterProjects);
filterButtons.forEach(button => button.addEventListener('click', () => {
  activeFilter = button.dataset.filter || 'all';
  filterButtons.forEach(item => item.classList.toggle('active', item === button)); filterProjects();
}));
const contactForm = document.querySelector('#contactForm');
contactForm?.addEventListener('submit', async event => {
  event.preventDefault();
  if (!contactForm.reportValidity()) return;
  const submitButton = contactForm.querySelector('button[type="submit"]');
  const note = document.querySelector('#formNote');
  const originalButton = submitButton?.innerHTML;
  const data = new FormData(contactForm);
  const payload = {
    name: String(data.get('name') || '').trim(),
    email: String(data.get('email') || '').trim(),
    subject: String(data.get('subject') || '').trim(),
    message: String(data.get('message') || '').trim(),
    _subject: `Portfolio message: ${String(data.get('subject') || '').trim()}`,
    _template: 'table',
    _captcha: 'false'
  };
  if (!payload.name || !payload.email || !payload.subject || !payload.message) return;
  if (submitButton) { submitButton.disabled = true; submitButton.textContent = 'Sending…'; }
  if (note) note.textContent = 'Sending your message…';
  try {
    const response = await fetch('https://formsubmit.co/ajax/aqburgos@ccc.edu.ph', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      body: JSON.stringify(payload)
    });
    const result = await response.json();
    if (!response.ok || String(result.success).toLowerCase() !== 'true') {
      throw new Error(result.message || 'Message could not be sent.');
    }
    if (note) note.textContent = 'Message sent successfully! Thank you for reaching out.';
    contactForm.reset();
  } catch (error) {
    if (note) note.textContent = 'Sorry, the message could not be sent right now. Please email aqburgos@ccc.edu.ph directly.';
  } finally {
    if (submitButton) { submitButton.disabled = false; submitButton.innerHTML = originalButton || 'Send message ↗'; }
  }
});

// Decorative portfolio viewer: projects open as a digital-design/original-sketch pair;
// certificates open as a single framed certificate. No empty placeholder panels are added.
function openImageLightbox(source, sketch = '', caption = '', kind = 'project', index = '') {
  let modal = document.querySelector('#imageLightbox');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'imageLightbox';
    modal.className = 'image-lightbox';
    modal.setAttribute('role', 'dialog');
    modal.setAttribute('aria-modal', 'true');
    modal.setAttribute('aria-label', 'Portfolio image presentation');
    modal.innerHTML = `
      <button class="lightbox-close" type="button" aria-label="Close image preview">×</button>
      <div class="presentation-shell">
        <div class="presentation-heading">
          <span class="presentation-kicker">✦ &nbsp; PORTFOLIO SHOWCASE &nbsp; ✦</span>
          <h2 class="presentation-title"></h2>
          <p class="presentation-subtitle"></p>
        </div>
        <div class="lightbox-gallery"></div>
        <p class="presentation-footer">♡ &nbsp; Designed with creativity and care &nbsp; ♡</p>
      </div>`;
    document.body.appendChild(modal);
    modal.addEventListener('click', event => {
      if (event.target === modal || event.target.closest('.lightbox-close')) closeImageLightbox();
    });
    document.addEventListener('keydown', event => {
      if (event.key === 'Escape') closeImageLightbox();
    });
  }

  const gallery = modal.querySelector('.lightbox-gallery');
  const isCertificate = kind === 'certificate';
  gallery.replaceChildren();
  gallery.classList.toggle('certificate-gallery', isCertificate);
  gallery.classList.toggle('single-image', !sketch);
  modal.classList.toggle('certificate-presentation', isCertificate);

  modal.querySelector('.presentation-title').textContent = caption || (isCertificate ? 'Certificate' : 'Featured Project');
  modal.querySelector('.presentation-subtitle').textContent = isCertificate
    ? 'Certificate of achievement'
    : 'A look at the finished design and its original concept';

  const items = isCertificate
    ? [{ src: source, label: 'Certificate', number: '01' }]
    : [
        { src: source, label: 'Digital design', number: '01' },
        ...(sketch ? [{ src: sketch, label: 'Original sketch', number: '02' }] : [])
      ];

  items.forEach(item => {
    const figure = document.createElement('figure');
    figure.className = 'lightbox-image-item';
    const label = document.createElement('span');
    label.className = 'presentation-ribbon';
    label.innerHTML = `<span aria-hidden="true">✦</span> ${item.number} · ${item.label}`;
    const imageFrame = document.createElement('div');
    imageFrame.className = 'presentation-image-frame';
    const img = document.createElement('img');
    img.src = item.src;
    img.alt = `${caption || 'Portfolio image'} — ${item.label}`;
    img.onload = () => {
      // Preserve each asset's natural proportions so logos and certificates never crop.
      const ratio = img.naturalWidth / img.naturalHeight;
      if (Number.isFinite(ratio) && ratio > 0) {
        imageFrame.style.setProperty('--image-ratio', String(ratio));
        imageFrame.classList.toggle('portrait-image', ratio < 0.9);
        imageFrame.classList.toggle('landscape-image', ratio > 1.1);
      }
    };
    img.onerror = () => {
      figure.classList.add('image-load-error');
      imageFrame.innerHTML = '<span class="presentation-image-error">Image could not be loaded.</span>';
    };
    imageFrame.appendChild(img);
    const footer = document.createElement('figcaption');
    footer.innerHTML = `<span aria-hidden="true">✦</span> ${item.label}`;
    figure.append(label, imageFrame, footer);
    gallery.appendChild(figure);
  });

  modal.querySelector('.presentation-footer').textContent = isCertificate
    ? '♡  A milestone in my learning journey  ♡'
    : '♡  Designed with creativity and care  ♡';
  modal.classList.add('open');
  document.body.classList.add('lightbox-open');
  modal.querySelector('.lightbox-close').focus();
}

function closeImageLightbox() {
  const modal = document.querySelector('#imageLightbox');
  modal?.classList.remove('open');
  document.body.classList.remove('lightbox-open');
}

// Make each complete project card open its presentation, not only the thumbnail.
document.querySelectorAll('.project-card').forEach(card => {
  const img = card.querySelector('.project-image-preview img');
  if (!img || !img.getAttribute('src')) return;
  card.tabIndex = 0;
  card.setAttribute('role', 'button');
  card.setAttribute('aria-label', `View project: ${card.querySelector('h3')?.textContent.trim() || img.alt}`);
  card.setAttribute('aria-haspopup', 'dialog');
  const show = () => openImageLightbox(
    img.getAttribute('src'),
    img.dataset.sketch || '',
    card.querySelector('h3')?.textContent.trim() || img.alt,
    'project'
  );
  card.addEventListener('click', event => {
    if (event.target.closest('a, button, input, .filter-chip')) return;
    show();
  });
  card.addEventListener('keydown', event => {
    if ((event.key === 'Enter' || event.key === ' ') && event.target === card) {
      event.preventDefault();
      show();
    }
  });
});

// Certificate tiles display their real certificate scan in the same decorated viewer.
document.querySelectorAll('.certificate-tile, .credential-link').forEach(button => {
  button.addEventListener('click', () => openImageLightbox(
    button.dataset.cert,
    '',
    button.dataset.certTitle || button.textContent.replace('↗', '').trim(),
    'certificate'
  ));
});

// Polished, staggered entrance motion for the main portfolio sections.
(() => {
  const motionTargets = document.querySelectorAll(
    '.section-heading, .about-grid, .skill-card, .timeline-item, .project-card, .education-card, .cv-section > *, .contact-grid, .hero-copy, .hero-visual'
  );
  if (!motionTargets.length) return;
  motionTargets.forEach((element, index) => {
    element.classList.add('motion-reveal');
    element.style.setProperty('--reveal-delay', `${(index % 4) * 85}ms`);
  });
  if (!('IntersectionObserver' in window) || window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    motionTargets.forEach(element => element.classList.add('is-visible'));
    return;
  }
  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('is-visible');
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.12, rootMargin: '0px 0px -35px 0px' });
  motionTargets.forEach(element => observer.observe(element));
})();

// Reliable offline CV download:
// The PDF is embedded as base64 so this works from file:// without hosting,
// fetch(), or a server. The browser creates a real PDF Blob on the user's click.
(() => {
  const cvPdfBase64 = '';
  const filename = 'Alteah_Anne_Q_Burgos_CV.pdf';
  const buttons = document.querySelectorAll('.cv-download-trigger');
  if (!buttons.length) return;

  buttons.forEach(button => {
    button.setAttribute('href', '#download-cv');
    button.setAttribute('download', filename);
    button.removeAttribute('target');
    button.addEventListener('click', event => {
      event.preventDefault();
      try {
        const binary = atob(cvPdfBase64);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
        const pdfBlob = new Blob([bytes], { type: 'application/pdf' });
        const objectUrl = URL.createObjectURL(pdfBlob);
        const downloadLink = document.createElement('a');
        downloadLink.href = objectUrl;
        downloadLink.download = filename;
        downloadLink.style.display = 'none';
        document.body.appendChild(downloadLink);
        downloadLink.click();
        downloadLink.remove();
        window.setTimeout(() => URL.revokeObjectURL(objectUrl), 60000);
      } catch (error) {
        console.error('CV download failed:', error);
        window.alert('The CV could not be downloaded. Please try another browser.');
      }
    });
  });
})();


// Extra portfolio polish: a subtle scroll progress line, with no external libraries.
(() => {
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const progress = document.createElement('div');
  progress.className = 'scroll-progress';
  progress.setAttribute('aria-hidden', 'true');
  document.body.appendChild(progress);

  let ticking = false;
  const updateProgress = () => {
    const scrollable = document.documentElement.scrollHeight - window.innerHeight;
    const amount = scrollable > 0 ? window.scrollY / scrollable : 0;
    progress.style.transform = `scaleX(${Math.min(1, Math.max(0, amount))})`;
    ticking = false;
  };
  window.addEventListener('scroll', () => {
    if (!ticking) {
      window.requestAnimationFrame(updateProgress);
      ticking = true;
    }
  }, { passive: true });
  window.addEventListener('resize', updateProgress, { passive: true });
  updateProgress();
})();
